// The counting pass (design §12.2 SELECTION_EVALUATION; 03 "Count the correct population"; 04 "Facts used as proof must be exact";
// decision D-DP-4) against an independent counter: every file of the corpus is generated by the test from data it keeps, and the
// expected physical rows, logical records per projection, billable units and association edges are computed from that data by the
// definitions of 03 — never by the parser. The evaluator runs for real (the platform's own parser, not a provider) in its isolated
// child (D-ISO-1), in bounded memory (distinct keys spill to the attempt scratch), and leaves its scratch empty. Hidden worksheets are
// counted only when the agency selects them with an acknowledgement; formulas are inert (a cached value is counted as stored, nothing
// is evaluated or fetched).
import assert from "node:assert/strict";
import { readdirSync } from "node:fs";
import { after, before, test } from "node:test";
import type { SelectionEvaluationInput, SelectionEvaluationOutcome } from "@kauro/application";
import { PRICING_DEFINITION, SELECTION_MANIFEST_SCHEMA_VERSION, type CsvParserChoice, type ProjectionDeclaration, type SelectionManifestDocument, type SourceTableId, type SourceTableRecord, type WorksheetParserChoice } from "@kauro/domain";
import { EVALUATOR_VERSION, IsolatedSelectionEvaluator, evaluationLimits, type EvaluationEvidence } from "../src/index.js";
import { SCOPE, admit, csvText, type Admitted } from "./support/admitted.js";
import { freshDir, listener, removeDir, sentinel, source, type Listener, type Sentinel } from "./support/harness.js";
import { buildWorkbook, type Cell, type RowSpec } from "./support/workbook.js";

let scratch: string;
let guard: Sentinel;
let net: Listener;

before(async () => {
  scratch = freshDir("evaluation");
  guard = sentinel();
  net = await listener();
});

after(async () => {
  await net.close();
  removeDir(scratch);
  removeDir(guard.dir);
});

// --- the corpus and its independent counts ---------------------------------------------------------------------------------------

interface Contact {
  readonly id: string;
  readonly name: string;
  readonly email: string;
  readonly company: string;
  readonly country: string;
}

/** 1,200 contacts: 37 companies repeated, some rows without a company (with or without a country), quoted commas and line breaks. */
const CONTACTS: ReadonlyArray<Contact> = Array.from({ length: 1_200 }, (_, k) => {
  const i = k + 1;
  const company = i % 13 === 0 ? "" : i % 211 === 0 ? "Multi\nLine Co" : `Company ${i % 37}`;
  return {
    id: String(i),
    name: i % 101 === 0 ? `Smith, "J" ${i}` : `Name ${i}`,
    email: `c${i}@example.test`,
    company,
    country: i % 26 === 0 ? "" : `C${i % 5}`,
  };
});
const CONTACT_HEADER = ["Id", "Name", "Email", "Company", "Country"];

/** The CSV of the contacts with one blank line after the 600th record. */
function contactsCsv(): Buffer {
  const rows = CONTACTS.map((c) => [c.id, c.name, c.email, c.company, c.country]);
  return Buffer.from(csvText([CONTACT_HEADER, ...rows.slice(0, 600)]) + "\n" + csvText(rows.slice(600)), "utf8");
}

/** 40 directory entries, Windows-1252 text (accented), semicolon-delimited, CRLF, one trailing blank line. */
const DIRECTORY: ReadonlyArray<readonly [string, string]> = Array.from({ length: 40 }, (_, k) => [`Société ${k + 1}`, k % 3 === 0 ? "España" : "México"] as const);
function directoryCsv(): Buffer {
  return Buffer.from(csvText([["Nom", "Pays"], ...DIRECTORY], ";", "\r\n") + "\r\n", "latin1");
}

interface Deal {
  readonly r: number;
  readonly hidden: boolean;
  /** Absent: the row has no element at all; empty: an element without cells. */
  readonly shape: "values" | "absent" | "empty";
  readonly owner: string;
}

/** Deals: rows 2..301, every 25th hidden, row 151 absent, row 152 an empty hidden row element; 1 in 7 without an owner. */
const DEALS: ReadonlyArray<Deal> = Array.from({ length: 300 }, (_, k) => {
  const i = k + 1;
  const r = i + 1;
  if (i === 150) return { r, hidden: false, shape: "absent", owner: "" };
  if (i === 151) return { r, hidden: true, shape: "empty", owner: "" };
  return { r, hidden: i % 25 === 0, shape: "values", owner: i % 7 === 0 ? "" : `owner${i % 97}@x.test` };
});

function dealsWorkbook(): Buffer {
  const rows: RowSpec[] = [{ r: 1, cells: ["DealId", "Title", "Amount", "OwnerEmail", "Stage"] }];
  for (const d of DEALS) {
    if (d.shape === "absent") continue;
    rows.push({ r: d.r, hidden: d.hidden, cells: d.shape === "empty" ? [] : [d.r - 1, `Deal ${d.r - 1}`, (d.r - 1) * 10.5, d.owner === "" ? null : d.owner, `S${d.r % 5}`] });
  }
  rows.push({ r: 305, hidden: true, cells: [] });
  const archive: Cell[][] = [["DealId", "OwnerEmail"], ...Array.from({ length: 50 }, (_, k) => [k + 1, `archived${k % 10}@x.test`] as Cell[])];
  const notes: Cell[][] = [["Note"], ["call back"], ["send offer"]];
  return buildWorkbook({ sheets: [{ name: "Deals", rows }, { name: "Archive", state: "hidden", rows: archive }, { name: "Notes", rows: notes }] });
}

/** 03, independently of the parser: ROW = one occurrence per counted row; REFERENCED_ENTITY = distinct non-empty keys + unkeyed rows whose field group is not empty; an edge per counted row whose target key is present. */
function referenced(rows: ReadonlyArray<{ readonly key: string; readonly fields: ReadonlyArray<string> }>): { readonly logical: number; readonly edges: number } {
  const keys = new Set<string>();
  let unkeyed = 0;
  let edges = 0;
  for (const r of rows) {
    if (r.key === "") {
      if (r.fields.some((f) => f !== "")) unkeyed += 1;
    } else {
      keys.add(r.key);
      edges += 1;
    }
  }
  return { logical: keys.size + unkeyed, edges };
}

// --- manifest helpers -----------------------------------------------------------------------------------------------------------

const CSV_UTF8: CsvParserChoice = { kind: "CSV", encoding: "UTF_8", delimiter: "COMMA", quote: "DOUBLE_QUOTE", header: { mode: "FIRST_RECORD" }, blankLines: "SKIP" };
const SHEET: WorksheetParserChoice = { kind: "WORKSHEET", header: { mode: "ROW", rowIndex: 0 }, formulas: "NOT_PRESENT", hiddenRows: "EXCLUDE", hiddenColumns: "INCLUDE", mergedCells: "AS_OBSERVED" };

function tableOf(a: Admitted, ordinal: number): SourceTableRecord {
  const t = a.tables.find((x) => x.ordinal === ordinal);
  assert.ok(t !== undefined, `table ${ordinal}`);
  return t;
}

type TableChoice = { readonly include: false; readonly reason: string } | { readonly include: true; readonly parser: CsvParserChoice | WorksheetParserChoice; readonly selectedColumns?: ReadonlyArray<number>; readonly acknowledged?: boolean };

function manifest(files: ReadonlyArray<{ readonly admitted: Admitted; readonly include: boolean; readonly tables: ReadonlyArray<TableChoice> }>, projections: ReadonlyArray<ProjectionDeclaration>, associations: SelectionManifestDocument["associations"] = []): SelectionManifestDocument {
  return {
    schemaVersion: SELECTION_MANIFEST_SCHEMA_VERSION,
    revisionId: SCOPE.revisionId as never,
    inventoryHash: "a".repeat(64),
    files: files.map((f) => (f.include ? { fileId: f.admitted.entry.file.fileId, origin: "THIS_REVISION", disposition: "INCLUDE" } : { fileId: f.admitted.entry.file.fileId, origin: "THIS_REVISION", disposition: "EXCLUDE", exclusionReason: "DUPLICATE_UPLOAD" })),
    tables: files.flatMap((f) =>
      f.tables.map((choice, ordinal) => {
        const t = tableOf(f.admitted, ordinal);
        const base = { tableId: t.tableId, fileId: t.fileId, structureHash: t.structureHash };
        if (!choice.include) return { ...base, disposition: "EXCLUDE" as const, exclusionReason: choice.reason };
        return {
          ...base,
          disposition: "INCLUDE" as const,
          parser: choice.parser,
          ...(choice.selectedColumns === undefined ? {} : { selectedColumns: choice.selectedColumns }),
          ...(choice.acknowledged === true ? { hiddenSheetAcknowledged: true as const } : {}),
        };
      }),
    ),
    projections,
    associations,
  };
}

function row(key: string, tableId: SourceTableId, objectKind: string, fieldOrdinals: ReadonlyArray<number>): ProjectionDeclaration {
  return { projectionKey: key, tableId, objectKind, kind: "ROW", fieldOrdinals };
}

function entity(key: string, tableId: SourceTableId, objectKind: string, keyOrdinals: ReadonlyArray<number>, fieldOrdinals: ReadonlyArray<number>, confirmed = true): ProjectionDeclaration {
  return { projectionKey: key, tableId, objectKind, kind: "REFERENCED_ENTITY", fieldOrdinals, keyOrdinals, ...(confirmed ? { keyConfirmed: true as const } : {}) };
}

async function evaluate(files: ReadonlyArray<Admitted>, selection: SelectionManifestDocument, overrides: { readonly limits?: Partial<SelectionEvaluationInput["limits"]>; readonly pricingDefinition?: string; readonly keysInMemory?: number } = {}): Promise<EvaluationEvidence> {
  const evaluator = new IsolatedSelectionEvaluator({ scratchRoot: scratch, distinctKeysInMemory: overrides.keysInMemory ?? 16 });
  assert.equal(evaluator.version, EVALUATOR_VERSION);
  const evidence = await evaluator.evaluateWithEvidence({ selection, files: files.map((f) => f.entry), limits: { ...evaluationLimits(), ...overrides.limits }, pricingDefinition: overrides.pricingDefinition ?? PRICING_DEFINITION });
  assert.deepEqual(readdirSync(scratch), [], "the evaluation leaves its scratch empty (distinct-key spills and shared strings included)");
  assert.ok(guard.unchanged(), "nothing written outside the scratch");
  assert.equal(net.connections(), 0, "no network attempt reached the test's listener");
  if (evidence.isolation !== undefined) {
    assert.deepEqual([evidence.isolation.mechanism, evidence.isolation.outsideWriteAttempts, evidence.isolation.networkAttempts, evidence.isolation.processAttempts], ["NODE_PERMISSION_CHILD", 0, 0, 0]);
  }
  return evidence;
}

function complete(outcome: SelectionEvaluationOutcome): Extract<SelectionEvaluationOutcome, { readonly result: "COMPLETE" }> {
  assert.equal(outcome.result, "COMPLETE", JSON.stringify(outcome.result === "COMPLETE" ? {} : outcome.failures));
  return outcome as Extract<SelectionEvaluationOutcome, { readonly result: "COMPLETE" }>;
}

function failures(outcome: SelectionEvaluationOutcome): ReadonlyArray<readonly [string, string | undefined]> {
  assert.notEqual(outcome.result, "COMPLETE");
  return (outcome as Exclude<SelectionEvaluationOutcome, { readonly result: "COMPLETE" }>).failures.map((f) => [f.code, f.tableId] as const);
}

function never(): AsyncIterable<Uint8Array> {
  throw new Error("an excluded file is never read");
}

// --- tests ------------------------------------------------------------------------------------------------------------------------

test("every selected file and table is counted: physical rows, logical records after projection, billable units, association edges — exact, per table and per projection", { timeout: 300_000 }, async () => {
  const contacts = await admit(contactsCsv(), "CSV", scratch);
  const directory = await admit(directoryCsv(), "CSV", scratch);
  const deals = await admit(dealsWorkbook(), "XLSX", scratch);
  const unused = await admit(Buffer.from("a,b\n1,2\n"), "CSV", scratch, never);
  const contactsTable = tableOf(contacts, 0).tableId;
  const directoryTable = tableOf(directory, 0).tableId;
  const dealsTable = tableOf(deals, 0).tableId;
  assert.deepEqual(deals.detected.map((t) => [t.ordinal, t.visibility]), [[0, "VISIBLE"], [1, "HIDDEN"], [2, "VISIBLE"]]);

  const projections = [
    row("CONTACT", contactsTable, "CONTACT", [0, 1, 2]),
    entity("COMPANY", contactsTable, "ACCOUNT", [3], [3, 4]),
    row("DIRECTORY", directoryTable, "ACCOUNT", [0, 1]),
    row("DEAL", dealsTable, "DEAL", [0, 1, 2]),
    entity("OWNER", dealsTable, "USER", [3], [3]),
  ];
  const associations = [
    { associationKey: "WORKS_AT", tableId: contactsTable, fromProjectionKey: "CONTACT", toProjectionKey: "COMPANY", relationType: "EMPLOYMENT" },
    { associationKey: "OWNED_BY", tableId: dealsTable, fromProjectionKey: "DEAL", toProjectionKey: "OWNER", relationType: "OWNERSHIP" },
  ];
  const selection = (blankLines: CsvParserChoice["blankLines"]): SelectionManifestDocument =>
    manifest(
      [
        { admitted: contacts, include: true, tables: [{ include: true, parser: { ...CSV_UTF8, blankLines } }] },
        { admitted: directory, include: true, tables: [{ include: true, parser: { kind: "CSV", encoding: "WINDOWS_1252", delimiter: "SEMICOLON", quote: "DOUBLE_QUOTE", header: { mode: "FIRST_RECORD" }, blankLines: "COUNT_AS_RECORDS" } }] },
        {
          admitted: deals,
          include: true,
          tables: [
            { include: true, parser: SHEET, selectedColumns: [0, 1, 2, 3] },
            { include: false, reason: "ARCHIVED_DATA" },
            { include: false, reason: "NOT_CUSTOMER_DATA" },
          ],
        },
        { admitted: unused, include: false, tables: [{ include: false, reason: "DUPLICATE_UPLOAD" }] },
      ],
      projections,
      associations,
    );

  // the independent counter
  const contactCompany = referenced(CONTACTS.map((c) => ({ key: c.company, fields: [c.company, c.country] })));
  const countedDeals = DEALS.filter((d) => !d.hidden);
  const dealOwner = referenced(countedDeals.filter((d) => d.shape === "values").map((d) => ({ key: d.owner, fields: [d.owner] })));
  const expected = {
    contactsRows: CONTACTS.length,
    directoryRows: DIRECTORY.length + 1,
    dealsRows: countedDeals.length,
    dealsHidden: DEALS.filter((d) => d.hidden).length,
    company: contactCompany.logical,
    worksAt: contactCompany.edges,
    owner: dealOwner.logical,
    ownedBy: dealOwner.edges,
  };
  // the definitions are exercised, not degenerate: repeated keys, unkeyed occurrences, hidden, absent and empty rows all occur
  assert.ok(expected.company < CONTACTS.length && expected.company > 37, "37 repeated companies, the multi-line one and the unkeyed occurrences");
  assert.ok(expected.worksAt < CONTACTS.length && expected.owner < expected.ownedBy);
  assert.equal(expected.dealsHidden, 12, "eleven hidden deals (the 150th is the absent row) and the empty hidden row");
  assert.equal(expected.dealsRows, 288, "rows 2..301 less the hidden ones; the absent row 151 is a row of the table");

  const evidence = await evaluate([contacts, directory, deals, unused], selection("SKIP"));
  const outcome = complete(evidence.outcome);
  const table = new Map(outcome.tables.map((t) => [t.tableId as string, t]));
  assert.deepEqual([...table.keys()].sort(), [contactsTable, directoryTable, dealsTable].sort(), "exactly the included tables — never an excluded table or file");
  assert.deepEqual([table.get(contactsTable)?.physicalRows, table.get(contactsTable)?.columnCount, table.get(contactsTable)?.excludedHiddenRows], [expected.contactsRows, 5, 0]);
  assert.deepEqual([table.get(directoryTable)?.physicalRows, table.get(directoryTable)?.columnCount], [expected.directoryRows, 2]);
  assert.deepEqual([table.get(dealsTable)?.physicalRows, table.get(dealsTable)?.excludedHiddenRows], [expected.dealsRows, expected.dealsHidden]);
  assert.ok(table.get(dealsTable)?.issues.includes("HIDDEN_ROWS_EXCLUDED"));
  const projection = new Map(outcome.projections.map((p) => [p.projectionKey, p]));
  assert.deepEqual(
    projections.map((p) => [p.projectionKey, projection.get(p.projectionKey)?.objectKind, projection.get(p.projectionKey)?.logicalRecords, projection.get(p.projectionKey)?.billable]),
    [
      ["CONTACT", "CONTACT", expected.contactsRows, true],
      ["COMPANY", "ACCOUNT", expected.company, true],
      ["DIRECTORY", "ACCOUNT", expected.directoryRows, true],
      ["DEAL", "DEAL", expected.dealsRows, true],
      ["OWNER", "USER", expected.owner, true],
    ],
    "every declared projection of R2-INITIAL is priced: billable = logical, before any deduplication",
  );
  assert.deepEqual(outcome.associations, [
    { associationKey: "WORKS_AT", edges: expected.worksAt },
    { associationKey: "OWNED_BY", edges: expected.ownedBy },
  ]);
  const logical = expected.contactsRows + expected.company + expected.directoryRows + expected.dealsRows + expected.owner;
  assert.deepEqual(outcome.populations, {
    physicalSourceRows: expected.contactsRows + expected.directoryRows + expected.dealsRows,
    logicalSourceRecords: logical,
    billableSourceUnits: logical,
    associationEdges: expected.worksAt + expected.ownedBy,
  });
  // the admitted bytes were re-read and re-verified; the excluded file was never opened
  assert.deepEqual(
    outcome.files.map((f) => [f.fileId, f.generation, f.sha256, f.bytes]),
    [contacts, directory, deals].map((a) => [a.entry.file.fileId, a.entry.file.providerGeneration, a.entry.file.sha256, a.entry.file.bytes]),
  );
  // bounded memory: the distinct keys went to the attempt scratch (16 in memory), and the counts are still exact
  assert.ok((evidence.spilledKeys.get("COMPANY") ?? 0) > 0 && (evidence.spilledKeys.get("OWNER") ?? 0) > 0, JSON.stringify([...evidence.spilledKeys]));
  assert.ok((evidence.isolation?.decompressedBytes ?? 0) > 0, "the workbook was expanded inside the isolated child");

  // the same bytes under the other blank-line choice: the blank line is a counted record of the contacts table, nothing else moves
  const counted = complete((await evaluate([contacts, directory, deals, unused], selection("COUNT_AS_RECORDS"), { keysInMemory: 1_000_000 })).outcome);
  const countedTables = new Map(counted.tables.map((t) => [t.tableId as string, t.physicalRows]));
  assert.deepEqual([countedTables.get(contactsTable), countedTables.get(directoryTable), countedTables.get(dealsTable)], [expected.contactsRows + 1, expected.directoryRows, expected.dealsRows]);
  assert.deepEqual(
    counted.projections.map((p) => [p.projectionKey, p.logicalRecords]),
    [["CONTACT", expected.contactsRows + 1], ["COMPANY", expected.company], ["DIRECTORY", expected.directoryRows], ["DEAL", expected.dealsRows], ["OWNER", expected.owner]],
    "the in-memory path (no spill) counts the same distinct keys",
  );
});

test("hidden worksheets are counted only when the agency selects them with an acknowledgement; formulas are inert — a cached value is counted as stored, a missing or erroring cache, an external dependency or a rejected formula fails the table, and nothing is evaluated or fetched", { timeout: 300_000 }, async () => {
  const url = `http://127.0.0.1:${net.port}/rate`;
  const workbook = buildWorkbook({
    sheets: [
      {
        name: "Accounts",
        rows: [
          ["Key", "Company", "Score", "Audit"],
          ["k1", "Globex", 1, { f: "SUM(C2:C4)" }],
          // a formula whose evaluation would give "Acme": its cache says "Globex", and the cache is what is counted
          ["k2", { f: '"Ac"&"me"', v: "Globex", t: "str" }, { f: "1+1", v: 2 }],
          ["k3", "Initech", 3],
        ],
        hiddenColumns: [[4, 4]],
      },
      { name: "Rates", rows: [["Key", "Rate"], ["r1", { f: `WEBSERVICE("${url}")`, v: "1.5", t: "str" }]] },
      { name: "Errors", rows: [["Key", "Ratio"], ["e1", { f: "1/0", v: "#DIV/0!", t: "e" }]] },
      { name: "Secret", state: "hidden", rows: [["Key"], ...Array.from({ length: 10 }, (_, k) => [`s${k}`] as Cell[])] },
      { name: "Vault", state: "veryHidden", rows: [["Key"], ...Array.from({ length: 4 }, (_, k) => [`v${k}`] as Cell[])] },
    ],
  });
  const file = await admit(workbook, "XLSX", scratch);
  assert.deepEqual(file.detected.map((t) => [t.visibility, t.formulaCache]), [
    ["VISIBLE", "SOME_MISSING"],
    ["VISIBLE", "EXTERNAL_DEPENDENCY"],
    ["VISIBLE", "ERROR_VALUES"],
    ["HIDDEN", "NOT_APPLICABLE"],
    ["VERY_HIDDEN", "NOT_APPLICABLE"],
  ]);
  const [accounts, rates, errors, secret, vault] = [0, 1, 2, 3, 4].map((o) => tableOf(file, o).tableId);
  const cached: WorksheetParserChoice = { ...SHEET, formulas: "USE_PRESENT_CACHED_VALUES_WITH_DISCLOSURE", hiddenColumns: "EXCLUDE" };
  const excluded = (reason: string): TableChoice => ({ include: false, reason });
  const only = (choices: ReadonlyArray<TableChoice>, projections: ReadonlyArray<ProjectionDeclaration>): SelectionManifestDocument => manifest([{ admitted: file, include: true, tables: choices }], projections);
  const accountProjections = [row("ROWS", accounts as SourceTableId, "ACCOUNT_ROW", [0, 2]), entity("COMPANY", accounts as SourceTableId, "ACCOUNT", [1], [1])];
  const rest = [excluded("REFERENCE_DATA"), excluded("NOT_CUSTOMER_DATA"), excluded("HIDDEN_WORKSHEET"), excluded("HIDDEN_WORKSHEET")];

  // cached values, the uncached formula in the excluded hidden column not counted: "Globex" twice (once as a cache) and "Initech"
  const inert = complete((await evaluate([file], only([{ include: true, parser: cached }, ...rest], accountProjections))).outcome);
  assert.deepEqual(inert.tables.map((t) => [t.tableId, t.physicalRows]), [[accounts, 3]], "hidden worksheets excluded: not counted, not listed");
  assert.deepEqual(inert.projections.map((p) => [p.projectionKey, p.logicalRecords]), [["ROWS", 3], ["COMPANY", 2]], "the formula was not evaluated: its cache is the value");

  // the same table with the hidden column counted: its formula has no cache
  const withHiddenColumn = await evaluate([file], only([{ include: true, parser: { ...cached, hiddenColumns: "INCLUDE" } }, ...rest], accountProjections));
  assert.deepEqual([withHiddenColumn.outcome.result, failures(withHiddenColumn.outcome)], ["ADMISSION_FAILED", [["FORMULA_CACHE_MISSING", accounts]]]);
  // formulas refused by the agency's policy, or a policy that says there are none
  const rejecting = await evaluate([file], only([{ include: true, parser: { ...cached, formulas: "REJECT_FORMULAS" } }, ...rest], accountProjections));
  assert.deepEqual(failures(rejecting.outcome), [["FORMULAS_REJECTED", accounts]]);
  const notPresent = await evaluate([file], only([{ include: true, parser: { ...cached, formulas: "NOT_PRESENT" } }, ...rest], accountProjections));
  assert.deepEqual(failures(notPresent.outcome), [["FORMULA_POLICY_MISMATCH", accounts]]);
  // a counted cell is one of a selected column: without the formula columns, rejecting formulas passes
  const firstColumn = complete((await evaluate([file], only([{ include: true, parser: { ...cached, formulas: "REJECT_FORMULAS" }, selectedColumns: [0] }, ...rest], [row("ROWS", accounts as SourceTableId, "ACCOUNT_ROW", [0])]))).outcome);
  assert.deepEqual(firstColumn.projections.map((p) => [p.projectionKey, p.logicalRecords]), [["ROWS", 3]]);

  // an external dependency (a web service call aimed at the test's listener) and an error cache fail their tables; nothing is fetched
  const external = await evaluate([file], only([excluded("OTHER"), { include: true, parser: cached }, { include: true, parser: cached }, excluded("HIDDEN_WORKSHEET"), excluded("HIDDEN_WORKSHEET")], [row("RATES", rates as SourceTableId, "RATE", [0, 1]), row("ERRORS", errors as SourceTableId, "RATIO", [0, 1])]));
  assert.deepEqual([...failures(external.outcome)].sort(), [["FORMULA_CACHE_ERROR", errors], ["FORMULA_EXTERNAL_DEPENDENCY", rates]].sort());
  assert.equal(net.connections(), 0, "the formula's URL was never requested");

  // hidden worksheets: included without the acknowledgement -> refused before a byte is parsed (no silent inclusion)
  const secretProjection = [row("SECRET", secret as SourceTableId, "SECRET_ROW", [0]), row("VAULT", vault as SourceTableId, "VAULT_ROW", [0])];
  const unacknowledged = await evaluate([file], only([excluded("OTHER"), excluded("OTHER"), excluded("OTHER"), { include: true, parser: SHEET }, { include: true, parser: SHEET }], secretProjection));
  assert.deepEqual([unacknowledged.outcome.result, failures(unacknowledged.outcome)], ["ADMISSION_FAILED", [["HIDDEN_SHEET_NOT_ACKNOWLEDGED", secret], ["HIDDEN_SHEET_NOT_ACKNOWLEDGED", vault]]]);
  assert.equal(unacknowledged.isolation, undefined, "nothing was parsed");
  // with the acknowledgement they are counted like any table
  const acknowledged = complete((await evaluate([file], only([excluded("OTHER"), excluded("OTHER"), excluded("OTHER"), { include: true, parser: SHEET, acknowledged: true }, { include: true, parser: SHEET, acknowledged: true }], secretProjection))).outcome);
  assert.deepEqual(acknowledged.tables.map((t) => [t.tableId, t.physicalRows]), [[secret, 10], [vault, 4]]);
  assert.deepEqual(acknowledged.populations, { physicalSourceRows: 14, logicalSourceRecords: 14, billableSourceUnits: 14, associationEdges: 0 });
});

test("the counting pass counts only the admitted bytes under the agency's choices: other bytes, an unknown pricing definition, a table of an excluded file, a revoked file, a parser of the other kind, an unconfirmed key, a projection over an unselected column, an invalid association, bytes undecodable as chosen and edges beyond the ceiling are refused, never silently dropped", { timeout: 300_000 }, async () => {
  const contacts = await admit(contactsCsv(), "CSV", scratch);
  const directory = await admit(directoryCsv(), "CSV", scratch);
  const contactsTable = tableOf(contacts, 0).tableId;
  const directoryTable = tableOf(directory, 0).tableId;
  const base = (choice: CsvParserChoice = CSV_UTF8): SelectionManifestDocument =>
    manifest(
      [
        { admitted: contacts, include: true, tables: [{ include: true, parser: choice, selectedColumns: [0, 1, 2, 3, 4] }] },
        { admitted: directory, include: false, tables: [{ include: false, reason: "DUPLICATE_UPLOAD" }] },
      ],
      [row("CONTACT", contactsTable, "CONTACT", [0, 1, 2]), entity("COMPANY", contactsTable, "ACCOUNT", [3], [3, 4])],
      [{ associationKey: "WORKS_AT", tableId: contactsTable, fromProjectionKey: "CONTACT", toProjectionKey: "COMPANY", relationType: "EMPLOYMENT" }],
    );
  complete((await evaluate([contacts, directory], base())).outcome);

  // other bytes than the admitted generation: the bytes are not counted at all
  const tampered = { ...contacts, entry: { ...contacts.entry, open: source(Buffer.concat([contacts.bytes, Buffer.from("9999,x,y,z,w\n")])) } };
  const other = await evaluate([tampered, directory], base());
  assert.deepEqual([other.outcome.result, failures(other.outcome)], ["ERROR", [["ACCEPTED_GENERATION_MISMATCH", undefined]]]);
  const pricing = await evaluate([contacts, directory], base(), { pricingDefinition: "R9-UNKNOWN" });
  assert.deepEqual([pricing.outcome.result, failures(pricing.outcome)], ["ERROR", [["PRICING_DEFINITION_UNKNOWN", undefined]]]);

  // the manifest against the admitted files and tables
  const manifestFailure = async (selection: SelectionManifestDocument, files: ReadonlyArray<Admitted> = [contacts, directory]): Promise<ReadonlyArray<readonly [string, string | undefined]>> => {
    const r = await evaluate(files, selection);
    assert.equal(r.outcome.result, "ADMISSION_FAILED");
    assert.equal(r.isolation, undefined, "refused before a byte is parsed");
    return failures(r.outcome);
  };
  const b = base();
  const directoryIncluded = { ...b, tables: [...b.tables, { tableId: directoryTable, fileId: directory.entry.file.fileId, structureHash: tableOf(directory, 0).structureHash, disposition: "INCLUDE" as const, parser: CSV_UTF8 }] };
  assert.deepEqual(await manifestFailure(directoryIncluded), [["SELECTION_UNKNOWN_TABLE", directoryTable]], "a table of an excluded file");
  const revoked = { ...contacts, entry: { ...contacts.entry, file: { ...contacts.entry.file, state: "ADMISSION_REVOKED" as const, admitted: false } } };
  assert.deepEqual(await manifestFailure(b, [revoked, directory]), [["INPUT_NOT_ADMITTED", undefined]]);
  assert.deepEqual(await manifestFailure({ ...b, tables: b.tables.map((t) => (t.tableId === contactsTable ? { ...t, parser: SHEET } : t)) }), [["PARSER_KIND_MISMATCH", contactsTable], ["PROJECTION_TABLE_NOT_INCLUDED", contactsTable], ["PROJECTION_TABLE_NOT_INCLUDED", contactsTable], ["ASSOCIATION_INVALID", contactsTable]]);
  assert.deepEqual(await manifestFailure({ ...b, projections: b.projections.map((p) => (p.kind === "REFERENCED_ENTITY" ? entity("COMPANY", contactsTable, "ACCOUNT", [3], [3, 4], false) : p)) }), [["KEY_NOT_CONFIRMED", contactsTable]]);
  assert.deepEqual(await manifestFailure({ ...b, tables: b.tables.map((t) => (t.tableId === contactsTable ? { ...t, selectedColumns: [0, 1, 2] } : t)) }), [["PROJECTION_COLUMN_NOT_SELECTED", contactsTable]]);
  assert.deepEqual(await manifestFailure({ ...b, associations: [{ associationKey: "WORKS_AT", tableId: contactsTable, fromProjectionKey: "COMPANY", toProjectionKey: "CONTACT", relationType: "EMPLOYMENT" }] }), [["ASSOCIATION_INVALID", contactsTable]]);

  // bytes the chosen encoding cannot decode: the table fails (no replacement characters, no skipped record)
  const wrongEncoding = manifest([{ admitted: directory, include: true, tables: [{ include: true, parser: { ...CSV_UTF8, delimiter: "SEMICOLON" } }] }], [row("DIRECTORY", directoryTable, "ACCOUNT", [0, 1])]);
  const undecodable = await evaluate([directory], wrongEncoding);
  assert.deepEqual(failures(undecodable.outcome), [["UNDECODABLE_BYTES", directoryTable]]);

  // edges beyond the association ceiling (03: crossing the qualified edge envelope blocks admission)
  const worksAt = referenced(CONTACTS.map((c) => ({ key: c.company, fields: [c.company, c.country] }))).edges;
  const ceiling = await evaluate([contacts, directory], base(), { limits: { associationCandidates: worksAt - 1 } });
  assert.deepEqual(failures(ceiling.outcome), [["ASSOCIATION_LIMIT", undefined]]);
  const atCeiling = complete((await evaluate([contacts, directory], base(), { limits: { associationCandidates: worksAt } })).outcome);
  assert.equal(atCeiling.populations.associationEdges, worksAt);
});
